package io.forgeloop.control.domain;
import jakarta.persistence.*;
@Entity public class VerificationGate { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @ManyToOne(optional=false) private FeatureRun run; private String name; private boolean required=true; private String state="PENDING"; protected VerificationGate(){} VerificationGate(FeatureRun run,String name){this.run=run;this.name=name;} public boolean matches(String candidate){return name.equals(candidate);} public void record(boolean passed){if("PASSED".equals(state)&&!passed)throw new IllegalStateException("Passed verification gate cannot be downgraded");state=passed?"PASSED":"FAILED";} public String getId(){return id;} public String getName(){return name;} public boolean isRequired(){return required;} public String getState(){return state;} }
